-- Hand-written (decisions P0.1, P0.2). Not generated by Drizzle Kit; policies are intentionally not declared in the Drizzle schema.
-- Runs as watheeq_owner, which owns the objects below.

-- The current tenant lives in the transaction-local setting app.tenant_id.
-- A missing or empty value raises instead of matching nothing, so a forgotten tenant context is an error, not an empty result.
-- (After one transaction sets it, PostgreSQL keeps the setting as an empty string on that connection, hence the empty check.)
CREATE FUNCTION app_current_tenant() RETURNS uuid
LANGUAGE plpgsql STABLE AS $$
DECLARE v text := current_setting('app.tenant_id', true);
BEGIN
  IF v IS NULL OR v = '' THEN
    RAISE EXCEPTION 'tenant context is not set' USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN v::uuid;
END $$;
--> statement-breakpoint

ALTER TABLE tenants ENABLE ROW LEVEL SECURITY;
--> statement-breakpoint
ALTER TABLE tenants FORCE ROW LEVEL SECURITY;
--> statement-breakpoint
ALTER TABLE users ENABLE ROW LEVEL SECURITY;
--> statement-breakpoint
ALTER TABLE users FORCE ROW LEVEL SECURITY;
--> statement-breakpoint

-- tenants: SELECT only, own row.
CREATE POLICY tenants_select ON tenants FOR SELECT
  USING (id = app_current_tenant());
--> statement-breakpoint

-- users: SELECT, INSERT, UPDATE within the current tenant. No DELETE policy.
CREATE POLICY users_select ON users FOR SELECT
  USING (tenant_id = app_current_tenant());
--> statement-breakpoint
CREATE POLICY users_insert ON users FOR INSERT
  WITH CHECK (tenant_id = app_current_tenant());
--> statement-breakpoint
CREATE POLICY users_update ON users FOR UPDATE
  USING (tenant_id = app_current_tenant())
  WITH CHECK (tenant_id = app_current_tenant());
--> statement-breakpoint

-- Grants for the runtime role, exactly as listed per table in the Phase 0 spec.
GRANT SELECT ON tenants TO watheeq_app;
--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE ON users TO watheeq_app;
